        const y = (row * h) / 18;
        ctx.fillStyle = `hsl(25 28% ${36 + random() * 7}%)`;
        ctx.fillRect(0, y, w, h / 18 - 1.2);
        for (let i = 0; i < 18; i++) {
          ctx.strokeStyle = `rgba(34,19,15,${0.03 + random() * 0.06})`;
